var LAB_SOURCES = {
  "01-pixel": "# First program - load immediates and store bytes to the framebuffer\n# Draws 3 pixels on the 32x32 framebuffer at 0x200 (1 byte/pixel)\n# Step 1 is canonical (addi, jal x0), step 2 is the shorthand (li, j, nop).\n.section .text\n.globl _start\n_start:\n    addi t0, zero, 1      # canonical: t0 = 1 (see li below)\n    addi t1, zero, 0x200 # canonical: t1 = 0x200\n    sb t0, 0(t1)      # pixel (0,0) - 1 byte per pixel\n    li t0, 5          # shorthand for addi t0, zero, 5: green\n    sb t0, 1(t1)      # pixel (1,0)\n    li t0, 8          # shorthand for addi t0, zero, 8: orange\n    sb t0, 2(t1)      # pixel (2,0)\n    nop               # shorthand for addi x0, x0, 0: one quiet cycle\n    jal x0, .         # halt: jump to self (j . is shorthand)",
  "02-fib": ".section .text\n.globl _start\n_start:\n    li a0, 7          # N = 7 (compute 7th Fibonacci number)\n    li t0, 0          # F(0) = 0\n    beq a0, zero, done\n    li t1, 1          # F(1) = 1\n    li t2, 1          # counter = 1\n    beq a0, t2, ready\nloop:\n    add t3, t0, t1    # t3 = F(n-1) + F(n-2)\n    addi t0, t1, 0    # canonical copy: t0 = t1 + 0\n    mv t1, t3         # shorthand for addi t1, t3, 0\n    addi t2, t2, 1    # counter++\n    blt  t2, a0, loop\nready:\n    mv a0, t1         # shorthand for addi a0, t1, 0 (13 for N=7)\ndone:\n    j done            # halt: shorthand for jal x0, done",
  "03-fib-ram": ".section .text\n.globl _start\n_start:\n    li a0, 7\n    li s0, 0x000      # zero-page RAM base (code lives at 0x600, far away)\n    li t0, 0\n    sw t0, 0(s0)      # RAM[0x00] = 0\n    beq a0, zero, done\n    li t1, 1\n    sw t1, 4(s0)      # RAM[0x004] = 1\n    li t2, 1\n    beq a0, t2, ready\nloop:\n    add t3, t0, t1\n    mv  t0, t1\n    mv  t1, t3\n    addi t2, t2, 1\n    slli t4, t2, 2\n    add  t5, s0, t4\n    sw   t3, 0(t5)    # RAM[s0 + t2*4] = t3\n    blt  t2, a0, loop\nready:\n    mv a0, t1\ndone:\n    j done",
  "04-branching": "# Branching - counted loop with explicit compare branches\n# Counts down from 8 to 3, writing pixel color at 0x200 each iteration\n# Canonical compare first (bne on two registers), shorthand after\n# (bnez against zero). No flags register anywhere.\n\n.section .text\n.globl _start\n_start:\n    li t0, 8          # counter = 8\n    li t1, 0x200      # framebuffer base\n    li t2, 3          # target = 3\n\nloop:\n    addi t0, t0, -1       # count down\n    sb   t0, 0(t1)        # write color at 0x200 - 1 byte/pixel\n    bne  t0, t2, loop     # canonical: branch on two registers\n\n    sub  t3, t0, t2       # t3 = 3 - 3 = 0 (the loop really ended at 3)\n    bnez t3, loop         # shorthand for bne t3, zero, loop: never taken\n\n    # store final value at next pixel to observe halt\n    sb   t0, 1(t1)\n    j    .                # halt: shorthand for jal x0, .\n\n# Exercises (see book/05-branching.md):\n# 1. Change BNE to BEQ and observe fall-through vs loop\n# 2. Use BLT/BGE to branch on signed less-than (e.g., blt t0, t2, loop)\n# 3. Count up with addi + bne; then translate bnez <-> bne ..., zero",
  "05-memory": "# Memory - RISC-V load/store with base+offset addressing\n# Demonstrates lw/sw, offsets, and base+offset (only modes in RISC-V)\n# Framebuffer at 0x200 is just memory-mapped I/O in the 4KB address space\n\n.section .text\n.globl _start\n_start:\n    li t0, 0x000      # zero-page RAM base (fast variables, game state)\n    li t1, 42\n    sw t1, 0(t0)      # absolute: sw t1, 0(t0)  -> *0x000 = 42\n    li t1, 99\n    sw t1, 4(t0)      # absolute+4: sw t1, 4(t0) -> *0x004 = 99\n\n    # indexed via register\n    li t2, 8          # offset = 8\n    li t1, 77\n    add t3, t0, t2    # t3 = base + offset\n    sw t1, 0(t3)      # store at 0x008\n\n    # load back and copy to framebuffer\n    lw t4, 0(t0)      # t4 = *0x000 (42)\n    lw t5, 4(t0)      # t5 = *0x004 (99)\n    add t4, t4, t5    # t4 = 141\n    li s0, 0x200      # FB base (keep separate reg)\n    sb t4, 0(s0)      # FB[0] = 141 & 0xF = 13 (light green) - 1 byte/pixel\n\n    # byte store/load\n    li t1, 0xAB\n    sb t1, 12(t0)     # byte at 0x00C\n    lbu s1, 12(t0)    # load byte unsigned -> s1=171\n    sb s1, 1(s0)      # FB[1] = 171 & 0xF = 11 (dark grey)\n\n    j .\n\n# Exercises:\n# 1. Try lh/lhu vs lw - what happens with alignment?\n# 2. Use slli to compute index*4 (like fib-ram) for array access\n# 3. Copy 0x000 vector to framebuffer 0x200 in a loop",
  "06-stack": "# Stack - manual push/pop via sp\n# Demonstrates push/pop via sp (software convention, grows down)\n# Stack grows down from 0x1FC (top of safe RAM, MEM_SIZE=0x1000)\n\n.section .text\n.globl _start\n_start:\n    li sp, 0x1FC       # init stack pointer (top of safe RAM, below the screen)\n\n    # push 3 values\n    li t0, 11\n    addi sp, sp, -4\n    sw t0, 0(sp)       # push 11\n\n    li t0, 22\n    addi sp, sp, -4\n    sw t0, 0(sp)       # push 22\n\n    li t0, 33\n    addi sp, sp, -4\n    sw t0, 0(sp)       # push 33 (top)\n\n    # pop in reverse and write to framebuffer at 0x200 (1 byte/pixel)\n    li t1, 0x200\n    lw t0, 0(sp)       # pop 33\n    addi sp, sp, 4\n    sb t0, 0(t1)\n\n    lw t0, 0(sp)       # pop 22\n    addi sp, sp, 4\n    sb t0, 1(t1)\n\n    lw t0, 0(sp)       # pop 11\n    addi sp, sp, 4\n    sb t0, 2(t1)\n\n    # Stack should be back at 0x1FC\n    # Write sp low nibble to FB[3] for visual check\n    andi t0, sp, 0xF\n    sb t0, 3(t1)\n\n    j .\n\n# Exercises:\n# 1. What happens if you forget addi sp,sp,4 after lw? (stack leak)\n# 2. Try pushing 8 values and popping - draw a mirrored pattern (push loop then pop loop)\n# 3. Use sp to save ra before a jal (preview of next lab)",
  "07-jumping": "# Jumping - jal/jalr subroutine calls and unconditional jumps\n# jal rd stores pc+4 in rd and jumps: it never touches the stack.\n# Saving ra with sw is software convention: your code pushes, your code\n# pops. A nested jal overwrites ra, so a function that calls another\n# must save ra first (see outer below; solutions ex01 shows the breakage).\n# First half spells everything canonically (explicit x0/x1), second half\n# uses the aliases (j, ret, jr) for the same observable FB = 1, 5, 15.\n\n.section .text\n.globl _start\n_start:\n    li t0, 0\n    jal x1, inc_one   # canonical call: x1 is ra, no stack involved\n    # t0 should be 1 here\n    li t1, 0x200\n    sb t0, 0(t1)       # FB[0] = 1 (1 byte/pixel)\n\n    jal x0, after     # canonical jump: x0 discards the return address\n    li t0, 99         # skipped\nafter:\n    addi t0, t0, 4    # t0 = 5\n    sb t0, 1(t1)      # FB[1] = 5\n\n    # nested call test: save ra on the stack before the inner call\n    li sp, 0x1FC\n    jal ra, outer     # jal ra is jal x1: same canonical instruction\n    sb t0, 2(t1)      # FB[2] should be 15\n    j .               # halt: shorthand for jal x0, .\n\ninc_one:\n    addi t0, t0, 1\n    jalr x0, 0(x1)    # canonical return through x1 (= ra)\n\nouter:\n    addi sp, sp, -4\n    sw ra, 0(sp)      # inner would overwrite ra (see solutions ex01)\n    addi t0, t0, 1    # t0 5->6\n    jal ra, inner\n    lw ra, 0(sp)\n    addi sp, sp, 4\n    ret               # shorthand for jalr x0, 0(x1)\n\ninner:\n    addi t0, t0, 9    # t0 6->15\n    jr ra             # shorthand for jalr x0, 0(ra)\n\n# Expected FB: 1, 5, 15",
  "08-alu": "# ALU - AND/OR/XOR bitwise ops and immediate masking\n# First half is canonical (and/andi, or, xori with explicit -1);\n# second half is the shorthand spellings (not, neg, seqz, snez)\n# for the same hardware. FB = dice 2-5, 15, 0, then fixed 5, 9, 0, 1.\n\n.section .text\n.globl _start\n_start:\n    # load random byte from 0xFE\n    li t0, 0xFE\n    lbu t1, 0(t0)      # t1 = random 0-255\n    andi t1, t1, 0x03  # mask low 2 bits -> 0-3\n    addi t1, t1, 2     # 2-5\n    # write result to framebuffer\n    li t2, 0x200\n    sb t1, 0(t2)       # FB[0] = 2-5\n\n    # OR example: combine nibbles\n    li t3, 0x0A        # 00001010\n    li t4, 0x05        # 00000101\n    or t5, t3, t4      # 00001111 = 15\n    sb t5, 1(t2)       # FB[1] = 15\n\n    # XOR toggle, canonical spelling\n    li t6, 0xFF\n    xori t6, t6, 0x0F  # 0xF0 -> low nibble 0\n    sb t6, 2(t2)       # FB[2] = 0\n\n    # --- shorthand half: same ALU, alias spellings ---\n    li t3, 0x0A        # 00001010\n    not t4, t3        # = xori t4, t3, -1 -> 0xFFFFFFF5\n    sb t4, 3(t2)       # FB[3] = 5\n\n    li t5, 7\n    neg t6, t5        # = sub t6, x0, t5 -> -7 = 0xFFFFFFF9\n    sb t6, 4(t2)       # FB[4] = 9\n\n    seqz s0, t5       # = sltiu s0, t5, 1 -> 0 (7 != 0)\n    sb s0, 5(t2)       # FB[5] = 0\n    snez s1, t5       # = sltu s1, x0, t5 -> 1 (0 < 7 unsigned)\n    sb s1, 6(t2)       # FB[6] = 1\n\n    j .\n\n# Exercises (see book/11-alu.md):\n# 1. Change mask 0x03 to 0x07 -> range 0-7, then +2 -> 2-9\n# 2. Use slli/srli to extract high nibble (>>4)\n# 3. sub + slt by hand (10 vs 3, both directions)\n# 4. Translate not/neg/seqz/snez to canonical and back; disasm must not change",
  "09-snake": "# Snake - capstone game (bare-metal RISC-V)\n# Framebuffer 0x200 (32x32, 1 byte/pixel), random at 0xFE, key at 0xFF (WASD)\n# Game state in zero-page RAM at 0x00: code lives at 0x600 above the screen,\n# state below it, so the full 32x32 arena is playable.\n# Layout: 0x00 DIR, 0x04 LEN (segment count), 0x08 APPLE (pixel addr),\n#         0x0C seg[0]=head, 0x10 seg[1], ... (one word per segment).\n# Directions use one bit each: 1=up 2=right 4=down 8=left.\n# Opposite pairs share one AND test: up|down, right|left.\n\n.equ FB,    0x200\n.equ RAND,   0xFE\n.equ KEY,    0xFF\n.equ STATE,  0x00\n.equ DIR,    0x0\n.equ LEN,    0x4\n.equ APPLE,  0x8\n.equ SEGS,   0xC\n\n.equ UP,     1\n.equ RIGHT,  2\n.equ DOWN,   4\n.equ LEFT,   8\n\n.section .text\n.globl _start\n_start:\n    li sp, 0x1FC      # stack top (grows down, code is far above at 0x600)\n    jal ra, init\n    jal ra, loop\n    j .               # loop never returns; halt if it ever does\n\n# init + loop subroutines, called once each from _start\ninit:\n    addi sp, sp, -4   # non-leaf: save ra before nested calls (see 07-jumping)\n    sw ra, 0(sp)\n    jal ra, init_snake\n    jal ra, gen_apple\n    lw ra, 0(sp)\n    addi sp, sp, 4\n    ret\n\ninit_snake:\n    li t0, STATE\n    li t1, RIGHT\n    sw t1, DIR(t0)    # start moving right\n    li t1, 2\n    sw t1, LEN(t0)    # 2 segments: head + 1 body\n    li t1, 0x411\n    sw t1, SEGS(t0)   # head = (17,16), middle of screen\n    li t1, 0x410\n    li t2, SEGS+4\n    add t2, t2, t0\n    sw t1, 0(t2)      # body = (16,16)\n    ret\n\ngen_apple:\n    li t0, RAND\n    lbu t1, 0(t0)     # random byte -> X 0-31\n    andi t1, t1, 0x1F\n    lbu t2, 0(t0)     # another random byte (0xFE changes every step)\n    andi t2, t2, 0x1F # Y 0-31 (whole screen: code is at 0x600, out of the way)\n    slli t2, t2, 5    # Y*32\n    add t1, t1, t2    # Y*32+X\n    li t2, FB\n    add t1, t1, t2    # pixel address 0x200-0x5FF\n    li t0, STATE\n    sw t1, APPLE(t0)\n    ret\n\n# main game loop: input, update state, render\nloop:\n    jal ra, read_keys\n    jal ra, check_collision\n    jal ra, update_snake\n    jal ra, draw_apple\n    jal ra, draw_snake\n    li t0, 400\nspin:\n    addi t0, t0, -1\n    bne t0, zero, spin\n    j loop\n\nread_keys:\n    li t0, KEY\n    lbu t1, 0(t0)     # ASCII of last key (0 if none)\n    li t2, 0x77       # 'w'\n    beq t1, t2, key_up\n    li t2, 0x64       # 'd'\n    beq t1, t2, key_right\n    li t2, 0x73       # 's'\n    beq t1, t2, key_down\n    li t2, 0x61       # 'a'\n    beq t1, t2, key_left\n    ret\nkey_up:\n    li t0, STATE\n    lw t1, DIR(t0)\n    andi t2, t1, DOWN # moving down? (opposite of up: reject reversal)\n    bne t2, zero, illegal\n    li t1, UP\n    sw t1, DIR(t0)\n    ret\nkey_right:\n    li t0, STATE\n    lw t1, DIR(t0)\n    andi t2, t1, LEFT\n    bne t2, zero, illegal\n    li t1, RIGHT\n    sw t1, DIR(t0)\n    ret\nkey_down:\n    li t0, STATE\n    lw t1, DIR(t0)\n    andi t2, t1, UP\n    bne t2, zero, illegal\n    li t1, DOWN\n    sw t1, DIR(t0)\n    ret\nkey_left:\n    li t0, STATE\n    lw t1, DIR(t0)\n    andi t2, t1, RIGHT\n    bne t2, zero, illegal\n    li t1, LEFT\n    sw t1, DIR(t0)\n    ret\nillegal:\n    ret\n\ncheck_collision:\n    addi sp, sp, -4   # non-leaf: check_apple calls gen_apple\n    sw ra, 0(sp)\n    jal ra, check_apple\n    jal ra, check_snake\n    lw ra, 0(sp)\n    addi sp, sp, 4\n    ret\n\ncheck_apple:\n    addi sp, sp, -4\n    sw ra, 0(sp)\n    li t0, STATE\n    lw t1, APPLE(t0)\n    lw t2, SEGS(t0)   # head address\n    bne t1, t2, no_apple\n    lw t1, LEN(t0)    # eat apple: grow one segment...\n    addi t1, t1, 1\n    sw t1, LEN(t0)\n    jal ra, gen_apple # ...and place a new apple\nno_apple:\n    lw ra, 0(sp)\n    addi sp, sp, 4\n    ret\n\ncheck_snake:\n    li t0, STATE\n    lw t1, SEGS(t0)   # head address\n    lw t2, LEN(t0)    # segment count\n    li t3, 1          # i = 1 (skip head)\ncs_loop:\n    bge t3, t2, no_snake\n    slli t4, t3, 2\n    add t4, t4, t0    # STATE + i*4\n    li t5, SEGS\n    add t4, t4, t5\n    lw t4, 0(t4)      # seg[i]\n    bne t4, t1, cs_next\n    j game_over       # head hit body\ncs_next:\n    addi t3, t3, 1\n    j cs_loop\nno_snake:\n    ret\n\nupdate_snake:\n    li t0, STATE\n    lw t1, LEN(t0)\n    addi t1, t1, -1   # i = LEN-1 (start at tail)\nus_loop:\n    blez t1, move_head # shift seg[1..LEN-1] only; seg[0] is rewritten below\n    slli t2, t1, 2\n    add t2, t2, t0    # STATE + i*4\n    li t3, SEGS\n    add t2, t2, t3    # &seg[i]\n    lw t3, -4(t2)     # seg[i-1]\n    sw t3, 0(t2)      # seg[i] = seg[i-1]: body follows head\n    addi t1, t1, -1\n    j us_loop\nmove_head:\n    lw t1, SEGS(t0)   # head address\n    lw t2, DIR(t0)\n    li t3, UP\n    beq t2, t3, go_up\n    li t3, RIGHT\n    beq t2, t3, go_right\n    li t3, DOWN\n    beq t2, t3, go_down\n    addi t1, t1, -1   # left: column - 1\n    andi t3, t1, 0x1F\n    li t4, 0x1F\n    beq t3, t4, game_over # wrapped past column 0\n    j store_head\ngo_up:\n    addi t1, t1, -32  # row - 1\n    li t3, FB\n    blt t1, t3, game_over # above row 0\n    j store_head\ngo_right:\n    addi t1, t1, 1    # column + 1\n    andi t3, t1, 0x1F\n    beq t3, zero, game_over # wrapped past column 31\n    j store_head\ngo_down:\n    addi t1, t1, 32   # row + 1\n    li t3, 0x600\n    bge t1, t3, game_over # below row 31 (0x200+1024 = 0x600)\nstore_head:\n    sw t1, SEGS(t0)\n    ret\n\ndraw_apple:\n    li t0, RAND\n    lbu t1, 0(t0)     # random color (low nibble shows)\n    li t0, STATE\n    lw t2, APPLE(t0)\n    sb t1, 0(t2)\n    ret\n\ndraw_snake:\n    li t0, STATE\n    lw t1, LEN(t0)\n    addi t1, t1, -1   # tail index\n    slli t1, t1, 2\n    add t1, t1, t0    # STATE + tail*4\n    li t2, SEGS\n    add t1, t1, t2\n    lw t2, 0(t1)      # tail pixel address\n    sb zero, 0(t2)    # erase tail (black)\n    lw t2, SEGS(t0)   # head pixel address\n    li t3, 1\n    sb t3, 0(t2)      # paint head white\n    ret\n\ngame_over:\n    li t0, STATE\n    lw t1, SEGS(t0)\n    li t2, 2\n    sb t2, 0(t1)      # red head marks the crash\nhalt:\n    jal x0, halt      # halt: jump to self (pc stops, like j . in 01-pixel)",
  "10-io": "# IO - the VM's outside world: memory-mapped ports\n# 0xFE: random byte (new value every instruction)\n# 0xFF: ASCII of last key pressed (0 headless, set by UI in debug)\n# 0x1000: print-char port (store a byte -> stdout)\n# Everything is a store or load: no syscalls, bare metal like the framebuffer.\n\n.section .text\n.globl _start\n_start:\n    # 1. random byte -> low nibble -> framebuffer\n    li t0, 0xFE\n    lbu t1, 0(t0)      # random 0-255\n    andi t1, t1, 0x0F  # 0-15\n    li t2, 0x200\n    sb t1, 0(t2)       # FB[0] = random color\n\n    # 2. print 'O' 'K' via stores to 0x1000\n    li t0, 0x1000\n    li t1, 79          # 'O'\n    sw t1, 0(t0)\n    li t1, 75          # 'K'\n    sw t1, 0(t0)\n\n    j .\n\n# Exercises:\n# 1. Print \"HI\" instead: change the two characters (72='H', 73='I')\n# 2. Print digit '5' (53) via a 0x1000 store\n# 3. Echo the last key: load 0xFF, mask the low nibble, store to FB[1]\n#    (press a key in 'just debug 10-io' and watch the pixel change)"
};
